bool hasCycle(Node* head) {
    Node* slow = head;
    Node* fast = head;
    while (fast != nullptr) {
        slow = slow->next;
        fast = fast->next->next;
        if (slow == fast) return true;
    }
    return false;
}

void reorder(Node* head) {
    if (!head || !head->next) return;
    Node *slow = head, *fast = head;
    while (fast->next && fast->next->next) {
        slow = slow->next;
        fast = fast->next->next;
    }
    Node *prev = nullptr, *cur = slow->next;
    while (cur) {
        Node* nxt = cur->next;
        cur->next = prev; prev = cur; cur = nxt;
    }
    Node *a = head, *b = prev;
    while (b) {
        Node *an = a->next, *bn = b->next;
        a->next = b; b->next = an;
        a = an; b = bn;
    }
}

