  void deleteAtIndex(int index);
};

questions.modelAnswer:
class MyLinkedList {
  struct Node { int val; Node* prev; Node* next; };
  Node sentinel_{0, &sentinel_, &sentinel_};       // circular: sentinel.next = head, sentinel.prev = tail
  int size_ = 0;

  Node* at(int index) {                            // 0 <= index < size_, walk from the closer end
    if (index < size_ / 2) {
      Node* p = sentinel_.next;
      while (index--) p = p->next;
      return p;
    }
    Node* p = sentinel_.prev;
    for (int i = size_ - 1; i > index; --i) p = p->prev;
    return p;
  }
  void insertBefore(Node* pos, int val) {
    Node* n = new Node{val, pos->prev, pos};
    pos->prev->next = n;
    pos->prev = n;
    ++size_;
  }
public:
  MyLinkedList() = default;
  MyLinkedList(const MyLinkedList&) = delete;
  MyLinkedList& operator=(const MyLinkedList&) = delete;
  ~MyLinkedList() {
    Node* p = sentinel_.next;
    while (p != &sentinel_) { Node* nx = p->next; delete p; p = nx; }
  }
  int get(int index) {
    if (index < 0 || index >= size_) return -1;
    return at(index)->val;
  }
  void addAtHead(int val) { insertBefore(sentinel_.next, val); }
  void addAtTail(int val) { insertBefore(&sentinel_, val); }
  void addAtIndex(int index, int val) {
    if (index < 0 || index > size_) return;
    insertBefore(index == size_ ? &sentinel_ : at(index), val);
  }
  void deleteAtIndex(int index) {
    if (index < 0 || index >= size_) return;
    Node* n = at(index);
    n->prev->next = n->next;
    n->next->prev = n->prev;
    delete n;
    --size_;
  }
};

