#include <random>

struct ListNode { int val; ListNode* next; };

class Solution {
  ListNode* head_;
  std::mt19937 rng_{std::random_device{}()};
public:
  explicit Solution(ListNode* head) : head_(head) {}

  // One pass, O(1) memory, works even if the length is unknown or huge:
  // node number i (1-based) becomes the answer with probability 1/i.
  int getRandom() {
    int result = head_->val, i = 1;
    for (ListNode* p = head_->next; p; p = p->next) {
      ++i;
      if (std::uniform_int_distribution<int>(0, i - 1)(rng_) == 0) result = p->val;
    }
    return result;
  }
};
